<?php require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/lib/monitor.php';global $CONFIG;if(PHP_SAPI!=='cli'&&!hash_equals((string)$CONFIG['CRON_SECRET'],(string)($_GET['key']??'')))fail('Não autorizado',401);$p=db();$sources=$p->query('SELECT * FROM sources WHERE active=1')->fetchAll();$terms=$p->query('SELECT * FROM search_terms WHERE active=1')->fetchAll();$entities=$p->query('SELECT * FROM case_entities WHERE active=1')->fetchAll();$summary=['sources'=>0,'found'=>0,'new'=>0,'errors'=>0];foreach($sources as$s){$found=$new=$rel=$rev=$discard=0;try{$raw=fetchUrl($s['url']);if($raw===false)throw new RuntimeException('Falha ao baixar feed');foreach(parseFeed($raw)as$i){$summary['found']++;$found++;if(!$i['title']||!$i['url'])continue;$canonical=normalizeUrl($i['url']);$hash=hash('sha256',mb_strtolower($i['title']).'|'.parse_url($canonical,PHP_URL_HOST));$dupe=$p->prepare('SELECT id FROM news WHERE canonical_url=? OR content_hash=? LIMIT 1');$dupe->execute([$canonical,$hash]);if($dupe->fetch())continue;$best=['weight'=>0,'term'=>''];$hay=mb_strtolower($i['title'].' '.$i['description']);foreach($terms as$t)if(mb_stripos($hay,$t['term'])!==false&&(int)$t['weight']>$best['weight'])$best=['weight'=>(int)$t['weight'],'term'=>$t['term']];[$score,$status,$reason,$matched]=analyze($hay,$entities,$best['weight']);$domain=parse_url($canonical,PHP_URL_HOST)?:'';$st=$p->prepare('INSERT INTO news(title,description,url,canonical_url,source_name,source_domain,published_at,image_url,status,is_new,is_read,category,search_term,content_hash,relevance_score,relevance_status,relevance_reason,analysis_source,matched_entities) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$i['title'],$i['description'],$i['url'],$canonical,$s['name'],$domain,$i['published_at'],$i['image_url'],'active',1,0,'Notícia',$best['term'],$hash,$score,$status,$reason,'metadata',json_encode($matched,JSON_UNESCAPED_UNICODE)]);$summary['new']++;$new++;if($status==='related')$rel++;elseif($status==='possibly_related')$rev++;else$discard++;}$p->prepare('UPDATE sources SET last_checked_at=NOW() WHERE id=?')->execute([$s['id']]);$p->prepare('INSERT INTO monitor_logs(source_id,status,total_results,new_results,related_results,review_results,discarded_results,message) VALUES(?,?,?,?,?,?,?,?)')->execute([$s['id'],'success',$found,$new,$rel,$rev,$discard,'Feed processado']);$summary['sources']++;}catch(Throwable$e){$summary['errors']++;$p->prepare('INSERT INTO monitor_logs(source_id,status,message) VALUES(?,?,?)')->execute([$s['id'],'error',mb_substr($e->getMessage(),0,500)]);}}if(PHP_SAPI==='cli'){echo json_encode($summary,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;exit;}respond($summary);
